const platformEnvironmentHasForeignReferences = `-- name: PlatformEnvironmentHasForeignReferences :one
SELECT EXISTS (
    SELECT 1 FROM eregion_platform_environments e
    WHERE e.id <> $1::text AND (
        e.current_revision_id IN (SELECT id FROM eregion_platform_environment_revisions WHERE environment_id = $1::text)
        OR e.desired_release_id IN (SELECT id FROM eregion_platform_releases WHERE environment_id = $1::text)
        OR e.applied_release_id IN (SELECT id FROM eregion_platform_releases WHERE environment_id = $1::text)
        OR e.serving_release_id IN (SELECT id FROM eregion_platform_releases WHERE environment_id = $1::text)
        OR e.serving_deployment_id IN (SELECT id FROM eregion_platform_deployments WHERE environment_id = $1::text))
    UNION ALL
    SELECT 1 FROM eregion_platform_releases r
    WHERE r.environment_id <> $1::text
      AND r.build_id IN (SELECT id FROM eregion_platform_builds WHERE environment_id = $1::text))
`

